{"content": "from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.security import APIKeyQuery, APIKeyHeader, APIKeyCookie, HTTPBearer, HTTPDigest, OpenIdConnect
from fastapi.testclient import TestClient

app = FastAPI()

api_key_query = APIKeyQuery(name="query_key")
api_key_header = APIKeyHeader(name="header_key")
api_key_cookie = APIKeyCookie(name="cookie_key")
http_bearer = HTTPBearer()
http_digest = HTTPDigest()
open_id_connect = OpenIdConnect()

@app.get("/query")
async def read_query(key: str = Depends(api_key_query)):
    return {"key": key}

@app.get("/header")
async def read_header(key: str = Depends(api_key_header)):
    return {"key": key}

@app.get("/cookie")
async def read_cookie(key: str = Depends(api_key_cookie)):
    return {"key": key}

@app.get("/bearer")
async def read_bearer(token: str = Depends(http_bearer)):
    return {"token": token}

@app.get("/digest")
async def read_digest(token: str = Depends(http_digest)):
    return {"token": token}

@app.get("/oidc")
async def read_oidc(token: str = Depends(open_id_connect)):
    return {"token": token}

client = TestClient(app)

def test_missing_credentials():
    endpoints = [
        ("/query", "APIKeyQuery"),
        ("/header", "APIKeyHeader"),
        ("/cookie", "APIKeyCookie"),
        ("/bearer", "HTTPBearer"),
        ("/digest", "HTTPDigest"),
        ("/oidc", "OpenIdConnect"),
    ]

    for path, name in endpoints:
        response = client.get(path)
        print(f"{name}: status={response.status_code}, headers={response.headers}")
        # Currently we expect 403, but the goal is 401.
        # For the repro to FAIL (meaning it's currently 403), we assert it should be 401.
        assert response.status_code == 401, f"{name} should return 401, but got {response.status_code}"

if __name__ == "__main__":
    try:
        test_missing_credentials()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Assertion failed: {e}")
        exit(1)
    except Exception as e:
        print(f"An error occurred: {e}")
        exit(1)
", "filepath": "/tmp/repro.py"}

