    return {"token": token}

@app.get("/digest")
async def read_digest(token = Depends(digest_scheme)):
    return {"token": token}

@app.get("/oidc")
async def read_oidc(token = Depends(oidc_scheme)):
    return {"token": token}

client = TestClient(app)

def test_api_key_query():
    response = client.get("/query")
    assert response.status_code == HTTP_403_FORBIDDEN

def test_http_bearer():
    response = client.get("/bearer")
    assert response.status_code == HTTP_403_FORBIDDEN

def test_http_digest():
    response = client.get("/digest")
    assert response.status_code == HTTP_403_FORBIDDEN

def test_open_id_connect():
    response = client.get("/oidc")
    assert response.status_code == HTTP_403_FORBIDDEN

